import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/10/","title":"第 10 课 · 主谓一致 Subject-Verb Agreement | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 10 课 · 主谓一致 Subject-Verb Agreement","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/10/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十课 语法专题 · 第十课 对应教材上册 P205–P211 · 先会判断单复数，再掌握四大原则：意义一致、形式一致、就近原则、就远原则。 考点地图 · 点击跳转 判断单复数基础：pen（n. 单数）/ apples（n. 复数）/ plays（v. 三...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 10 课 · 主谓一致 Subject-Verb Agreement\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/10/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 10 课 · 主谓一致 Subject-Verb Agreement"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十课 语法专题 · 第十课 对应教材上册 P205–P211 · 先会判断单复数，再掌握四大原则：意义一致、形式一致、就近原则、就远原则。 考点地图 · 点击跳转 判断单复数基础：pen（n. 单数）/ apples（n. 复数）/ plays（v. 三..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 10 课 · 主谓一致 Subject-Verb Agreement"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/10/"}]]},"readingTime":{"minutes":72.64,"words":21791},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/10.md","headers":[]}`),u={name:`10.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0010-subject-verb-agreement.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第十课`,-1)]),l[10]||=r(`<p>语法专题 · 第十课</p><p>对应教材上册 P205–P211 · 先会判断单复数，再掌握四大原则：意义一致、形式一致、就近原则、就远原则。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1">判断单复数基础：pen（n. 单数）/ apples（n. 复数）/ plays（v. 三单形式）/ eat（v. 复数形式）/ am, is（be 单数）/ are（be 复数）</a></li><li><a href="#pt-1">四大原则：<strong>意义一致、形式一致、就近原则、就远原则</strong></a></li></ol></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>基础回顾 · 三单变化 一般现在时中，主语为第三人称单数（<strong>非 I、非 you、非复数</strong>）时，谓语动词变三单：一般加 -s；s/x/ch/sh/o 结尾加 -es；辅音字母+y 去 y 变 i 加 es；特殊 have → has。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>开篇易错题 My favorite fruit ____.（A. are apples　B. is apples　C. is an apple　D. is apple）</p><p><strong>答案 B</strong> —— 主语 fruit（不可数）决定谓语用单数 is；表语 apples 复数不影响谓语。</p></div><h2 id="一、意义一致原则-教材-p205-208" tabindex="-1"><a class="header-anchor" href="#一、意义一致原则-教材-p205-208"><span>一、意义一致原则（教材 P205-208）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 一、意义一致原则（教材 P205-208）</p><ul><li><strong>目标</strong>：主线是“谓语看意义不看形式”：先把集体名词、数量主语、-ics 学科、不定代词、分数与 the + adj.、what 从句、a number of、and 并列这八类主语的单复数意义判定清楚。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>主谓一致·意义一致原则（总纲）</code> <code>集体名词作主语的三分法</code> <code>时间 / 距离 / 金钱 / 速度复数名词作主语</code> <code>以 -ics 结尾的学科名词作主语</code> <code>不定代词作主语</code> <code>分数 / 百分数 / the rest + of + 名词作主语</code> <code>“the + 形容词”作主语</code> <code>what / whether 等主语从句作主语</code> <code>a number of 与 the number of</code> <code>and 连接并列主语的一致</code></li></ul></div><h3 id="一、意义一致原则-教材-p205-208-·-小步学" tabindex="-1"><a class="header-anchor" href="#一、意义一致原则-教材-p205-208-·-小步学"><span>一、意义一致原则（教材 P205-208） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>主谓一致：动词跟谁配合</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>主谓一致先问一句：主语到底算单数还是复数</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>集体名词三分法：三群恒复数，家庭看意义，设备恒单数</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>看着像复数、其实算单数的四类主语</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>分数、the + adj. 与主语从句：三种“看后半截”的主语</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>a number of 与 the number of：一个字母决定单复数</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>and 连接的主语：同一个人用单数，两样东西用复数</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：合上书，说出集体名词三分法、三类“看着像复数其实算单数”的主语，以及 a number of 与 the number of 的区别。</p><div class="hint-container tip"><p class="hint-container-title">主谓一致先问一句：主语到底算单数还是复数</p><p><strong>句意</strong>：My favorite fruit is apples. 意思是“我最喜欢的水果是苹果”——主语是单数的 fruit，表语却是复数的 apples，谓语仍然用 is。</p><p><strong>拆解</strong></p><ul><li>My favorite fruit 是主语：中心词是 fruit，作“水果”讲时是不可数名词</li><li>is 是系动词，跟着主语 fruit 用单数</li><li>apples 是表语，说明“是什么水果”，它不参与主谓一致</li><li>很多人误选 are，是因为眼睛盯着表语 apples，而不是主语 fruit</li></ul><p><strong>语法</strong>：主谓一致的第一原则是意义一致：谓语动词的单复数取决于主语的单复数意义，而不是它的语法形式。判断三步：① 找主语中心词（先剥掉修饰语、定语从句）；② 判断这个中心词是单数意义还是复数意义；③ 再让谓语跟它一致。</p><p>正例：My favorite fruit is apples.（主语 fruit 不可数 → is）；The humor they like is different.（真主语是 the humor）；A life lived for others is a life worthwhile.（真主语是 a life） 反例：My favorite fruit are apples. ×（被表语 apples 带偏）；The humor they like are different. ×（被定语从句里的 they 带偏） 适用边界：“看主语不看表语”是通用规则；但当主语是主系表结构里的从句时（What we need is…），谓语反而要看表语——那是 what 从句的特殊处理，见本节第四张卡片。</p><p><strong>口诀</strong>：谓语只跟主语走，表语再花哨也不算数 —— 先把主语的中心词圈出来，再决定谓语；眼睛离开表语。</p></div><div class="hint-container tip"><p class="hint-container-title">集体名词三分法：三群恒复数，家庭看意义，设备恒单数</p><p><strong>句意</strong>：The police are looking for the thief. 意思是“警察正在寻找小偷”；My family is a big one. 意思是“我的家庭是个大家庭”，而 My family are all music lovers. 意思是“我的家人都是音乐爱好者”。</p><p><strong>拆解</strong></p><ul><li>The police are：police 表示“警方、警察们”，永远是复数概念 → 谓语用 are</li><li>My family is a big one：这里 family 指“一个家庭”这个整体 → 单数</li><li>My family are all music lovers：这里指“家里的每个人”，强调成员 → 复数</li><li>The equipment in our school is very advanced：equipment 不可数，恒用单数</li></ul><p><strong>语法</strong>：集体名词分三类：① 恒复数（people、police、cattle）；② 可单可复（family、team、class、audience、committee、crew、government、jury），强调整体用单数、强调成员用复数；③ 恒单数（equipment、furniture、luggage、foliage 作不可数名词用单数）。</p><p>正例：The police are looking for the thief.（三群恒复数）；My family is a big one.（整体 → 单数）；My family are all music lovers.（成员 → 复数）；The equipment in our school is very advanced.（不可数 → 单数） 反例：The police is coming. ×（police 恒复数）；The equipment are new. ×（equipment 不可数，没有复数） 适用边界：判断“整体还是成员”看句子在说什么：比大小、比数量、说“是一个……”时是整体；说“各自在做什么”、句中出现 all、each 等词时是成员。equipment、furniture、luggage 这类名词根本没有复数形式，不要写 equipments。</p><p><strong>口诀</strong>：三群恒复数：people、police、cattle；集体看意义，整体单、成员复 —— 看到 police/people/cattle 直接上复数；看到 family/team/government 先问一句“说的是这个集体，还是里面的人”。</p></div><div class="hint-container tip"><p class="hint-container-title">看着像复数、其实算单数的四类主语</p><p><strong>句意</strong>：Ten years is a long time. 意思是“十年是很长的一段时间”；Physics is not an easy subject for some students. 意思是“物理对一些学生来说不是容易的学科”。</p><p><strong>拆解</strong></p><ul><li>Ten years is：时间长度被看成一个整体，用单数</li><li>Five hundred dollars is not a small amount of money：金额也是整体</li><li>Physics is：-ics 结尾的学科名词形式是复数，意义是单数</li><li>Everyone is here. / Nothing is impossible.：不定代词作主语一律单数</li></ul><p><strong>语法</strong>：四类“形式复数、意义单数”的主语：① 时间 / 距离 / 金钱 / 重量 / 速度等复数名词看作整体（three weeks is、ten pounds is）；② -ics 结尾的学科名词（physics、mathematics、economics）；③ 不定代词 everyone、everybody、someone、somebody、anyone、anybody、no one、nobody、nothing、each；④ one + 单数名词 + and a half（One apple and a half is on the table.）。</p><p>正例：Ten years is a long time.；Five hundred dollars is not a small amount of money.；One hundred and twenty kilometers per hour is usually the speed limit.；Physics is not an easy subject for some students.；Nothing is impossible. 反例：Ten years are a long time. ×（看作整体）；Physics are difficult. ×（学科名用单数）；Everyone are here. ×（不定代词单数） 适用边界：“整体”的判定只看句子是否把它当作一个量：说“十年是漫长的一段时间”“这笔钱不少”时是整体；若强调“一年一年地过去”这类个体性，也可能用复数。学科名词若换成别的意思（如 economics 指“经济情况”）则另当别论。</p><p><strong>口诀</strong>：时间金钱算一笔，学科名字算一门，everyone/nothing 算一个 —— 把主语先归成一个“量”或“一个人/物”，谓语自然用单数。</p></div><div class="hint-container tip"><p class="hint-container-title">分数、the + adj. 与主语从句：三种“看后半截”的主语</p><p><strong>句意</strong>：Forty percent of the water is polluted. 意思是“百分之四十的水被污染了”；The rich are not always happy. 意思是“富人并不总是幸福的”；What we need are good teachers. 意思是“我们需要的是好老师”。</p><p><strong>拆解</strong></p><ul><li>Forty percent of the water is：分数作主语时，谓语跟 of 后面的名词（water 不可数 → is）</li><li>Part of the students have gone home：of 后面是复数 students → 复数</li><li>The rich are：the + 形容词表一类人 → 复数</li><li>What we need are good teachers：主系表结构里谓语看表语（good teachers 复数 → are）</li></ul><p><strong>语法</strong>：① 分数、百分数、part、the rest + of + 名词作主语：谓语与 of 后的名词一致，分数写法是分子大于 1 时分母加 s（two-thirds）。② the + 形容词作主语：表一类人 → 复数；表抽象概念 → 单数（The new is certain to replace the old.）。③ what / whether 等主语从句作主语：谓语常用单数；主系表结构则看表语。</p><p>正例：7% of them are in published online material.（them 复数 → are）；The rest of the workers are still very tired.；The rich are not always happy.；The new is certain to replace the old.；What we need is a good teacher. / What we need are good teachers. 反例：7% of them is… ×（of 后是复数）；The disabled is well taken care of. ×（表一类人用复数）；What we need is good teachers. ×（主系表结构看表语） 适用边界：the + adj. 到底指“人”还是“概念”要看语境：the rich、the poor、the disabled 通常指人；the new、the old、the beautiful 常指抽象概念。分数作主语时若 of 后是不可数名词，谓语仍用单数。</p><p><strong>口诀</strong>：分数看 of 后；the + adj. 看是不是人；what 从句看表语 —— 这三类主语都不能只看开头那几个词，要往后看一眼再定谓语。</p></div><div class="hint-container tip"><p class="hint-container-title">a number of 与 the number of：一个字母决定单复数</p><p><strong>句意</strong>：A number of students are playing basketball on the playground. 意思是“许多学生正在操场上打篮球”；The number of students in our school is about 2000. 意思是“我们学校学生的数目大约是 2000 人”。</p><p><strong>拆解</strong></p><ul><li>A number of students are：a number of = “许多”，中心是后面的复数名词 → 谓语复数</li><li>The number of students is：the number of = “……的数目”，中心是 number 这个单数名词 → 谓语单数</li><li>两句结构几乎一样，差别只在冠词 a / the</li></ul><p><strong>语法</strong>：a number of + 复数名词（= many，许多）→ 谓语复数；the number of + 复数名词（= “……的数目”）→ 谓语单数。a large number of 与 a number of 同理。同类结构还有 a variety of（许多，复数）与 the variety of（……的种类，单数）。</p><p>正例：A number of students are playing basketball.（许多学生）；The number of students is about 2000.（学生的数目）；So far, a large number of forests have been destroyed.（许多森林） 反例：The number of students are about 2000. ×（数目用单数）；A number of students is playing. ×（许多学生用复数） 适用边界：判断依据是“这个短语的中心词是谁”：a number of 里 number 已经虚化成“许多”，中心落到后面的名词；the number of 里 number 是实打实的中心词。</p><p><strong>口诀</strong>：the number 单，a number 复 —— 把 the 读成“这个数目”，把 a 读成“许多”；读出来就知道谓语用单还是用复。</p></div><div class="hint-container tip"><p class="hint-container-title">and 连接的主语：同一个人用单数，两样东西用复数</p><p><strong>句意</strong>：The writer and poet is coming to give us a speech. 意思是“这位作家兼诗人要来做演讲”（同一个人）；War and peace is a constant theme in history. 意思是“战争与和平是历史中恒定的主题”（一个整体概念）。</p><p><strong>拆解</strong></p><ul><li>The writer and poet：writer 前只有一个 the，说明是“作家兼诗人”一个人 → 单数 is</li><li>若是 The writer and the poet，两个 the 表示两个人 → 复数</li><li>War and peace：两个词合成一个抽象整体（战争与和平）→ 单数</li><li>iron and steel 钢铁、law and order 治安、a knife and fork 刀叉也是整体概念</li></ul><p><strong>语法</strong>：and 连接两个主语时：指同一个人、同一件事或同一概念 → 谓语用单数；指两个不同的人或物 → 用复数。固定的整体概念搭配有 iron and steel、law and order、bread and butter、a watch and chain、a knife and fork、a coat and tie、aim and end、ruth and honesty。</p><p>正例：The writer and poet is coming.（同一个人的两种身份）；The black and white cat are two different cats.（两只猫 → 复数）；War and peace is a constant theme in history.（整体概念）；A knife and fork is on the table.（一副刀叉） 反例：The writer and poet are coming. ×（同一个人，用单数）；Bread and butter are my favorite breakfast. ×（固定整体概念用单数） 适用边界：判定线索是冠词和语境：第二个名词前有没有 the、是不是两个人；以及两个词是否已经固定成一个概念。说“黑猫和白猫是不同的猫”这类两样东西时，一定用复数。</p><p><strong>口诀</strong>：一个 the 是一个人，两个 the 是两个人；固定搭配算一样东西 —— 先数“几个人/几样东西”，再决定谓语的单复数。</p></div><p>主语和谓语的一致关系取决于主语的<strong>单、复数意义</strong>，而不是语法上的单、复数形式。</p><h3 id="_1-集体名词作主语" tabindex="-1"><a class="header-anchor" href="#_1-集体名词作主语"><span>1. 集体名词作主语</span></a></h3><table><thead><tr><th>类型</th><th>名词</th><th>谓语</th><th>例句</th></tr></thead><tbody><tr><td><strong>通常作复数的集体名词</strong>（&quot;三群&quot;）</td><td><strong>people</strong>（人们）、<strong>police</strong>（警察）、<strong>cattle</strong>（牛）</td><td>复数</td><td>The police <strong>are</strong> looking for the thief. 警察正在寻找小偷。</td></tr><tr><td><strong>可作单数或复数的集体名词</strong></td><td>family（家庭）、team（团队）、class（班级）、audience（观众）、committee（委员会）、crew（工作人员）、government（政府）、jury（陪审团）等</td><td>强调整体→单数；强调集体中的个体成员→复数</td><td>My family <strong>is</strong> a big one. 我的家庭是个大家庭。 My family <strong>are</strong> all music lovers. 我的家人都是音乐爱好者。</td></tr><tr><td><strong>常作不可数的集体名词</strong></td><td>equipment（设备）、furniture（家具）、luggage（行李）、foliage（叶子）等</td><td>没有复数形式，用单数</td><td>The equipment in our school <strong>is</strong> very advanced. 我们学校的设备非常先进。</td></tr></tbody></table><h3 id="_2-时间、距离、金钱、重量等复数名词作主语-教材-p206" tabindex="-1"><a class="header-anchor" href="#_2-时间、距离、金钱、重量等复数名词作主语-教材-p206"><span>2. 时间、距离、金钱、重量等复数名词作主语（教材 P206）</span></a></h3><p>通常被看作<strong>一个整体</strong>，谓语动词用<strong>单数</strong>：</p><p><strong>Ten years is</strong> a long time. 十年是很长的一段时间。</p><p><strong>Five hundred dollars is</strong> not a small amount of money. 五百美元不是一笔小数目。</p><h3 id="_3-以-ics-结尾的学科名词作主语-教材-p206" tabindex="-1"><a class="header-anchor" href="#_3-以-ics-结尾的学科名词作主语-教材-p206"><span>3. 以 -ics 结尾的学科名词作主语（教材 P206）</span></a></h3><p>谓语动词用<strong>单数</strong>：physics（物理）、mathematics（数学）、economics（经济学）等。</p><p><strong>Physics is</strong> not an easy subject for some students. 物理对一些学生来说不是容易的学科。</p><h3 id="_4-不定代词作主语-教材-p206" tabindex="-1"><a class="header-anchor" href="#_4-不定代词作主语-教材-p206"><span>4. 不定代词作主语（教材 P206）</span></a></h3><p>everyone, everybody, someone, somebody, anyone, anybody, no one, nobody 等作主语时，谓语动词用<strong>单数</strong>：</p><p><strong>Everyone is</strong> here. 大家都到了。/ <strong>Somebody is</strong> waiting for you at the gate. 有人在门口等你。</p><h3 id="_5-分数、百分数修饰的名词作主语-教材-p206" tabindex="-1"><a class="header-anchor" href="#_5-分数、百分数修饰的名词作主语-教材-p206"><span>5. 分数、百分数修饰的名词作主语（教材 P206）</span></a></h3><p><strong>结构：分数/百分数 + of + 名词</strong>作主语，谓语与 <strong>of 后的名词</strong>保持一致：</p><p><strong>Forty percent of</strong> the water <strong>is</strong> polluted.</p><p><strong>Part of</strong> the students <strong>have</strong> gone home.</p><h3 id="_6-the-adj-作主语-教材-p207" tabindex="-1"><a class="header-anchor" href="#_6-the-adj-作主语-教材-p207"><span>6. &quot;the + adj.&quot; 作主语（教材 P207）</span></a></h3><p>表示<strong>一类人</strong> → 谓语用<strong>复数</strong>：<strong>The rich are</strong> not always happy. 富人并不总是幸福的。</p><p>表示<strong>抽象概念</strong> → 谓语用<strong>单数</strong>。</p><h3 id="_7-what-引导的主语从句-教材-p207" tabindex="-1"><a class="header-anchor" href="#_7-what-引导的主语从句-教材-p207"><span>7. what 引导的主语从句（教材 P207）</span></a></h3><p>从句作主语，谓语动词<strong>常用单数</strong>；若主句为<strong>主系表结构</strong>，谓语单复数取决于<strong>表语名词的单复数</strong>：</p><p><strong>What</strong> we eat <strong>affects</strong> our long-term health.</p><p>What we need <strong>are</strong> good teachers.（我们需要的是好老师。）</p><p>What we need <strong>is</strong> a good teacher.（我们需要的是一位好老师。）</p><h3 id="_8-a-number-of-the-number-of-教材-p207" tabindex="-1"><a class="header-anchor" href="#_8-a-number-of-the-number-of-教材-p207"><span>8. a number of / the number of（教材 P207）</span></a></h3><table><thead><tr><th>结构</th><th>意义</th><th>谓语</th><th>例句</th></tr></thead><tbody><tr><td><strong>a number of</strong> + 复数名词</td><td>&quot;许多……&quot;（复数意义）</td><td>复数</td><td><strong>A number of</strong> students <strong>are</strong> playing basketball on the playground. 许多学生正在操场上打篮球。</td></tr><tr><td><strong>the number of</strong> + 复数名词</td><td>&quot;……的数目&quot;（单数意义）</td><td>单数</td><td><strong>The number of</strong> students in our school <strong>is</strong> about 2000. 我们学校学生的数目大约是 2000 人。</td></tr></tbody></table><h3 id="_9-and-连接的两个词作主语-教材-p207" tabindex="-1"><a class="header-anchor" href="#_9-and-连接的两个词作主语-教材-p207"><span>9. and 连接的两个词作主语（教材 P207）</span></a></h3><p>并列主语若是<strong>同一个人、同一事、同一概念</strong> → 谓语用<strong>单数</strong>，否则用<strong>复数</strong>：</p><p><strong>The writer and poet is</strong> coming to give us a speech. 这位<strong>作家兼诗人</strong>（同一人）要来做演讲。</p><p><strong>The black and white cat are</strong> two different cats. 黑猫和白猫（两只猫）是不同的猫。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>并列结构表整体概念（谓语用单数） iron and steel 钢铁；law and order 治安；bread and butter 黄油面包；a watch and chain 一块带链的表；a knife and fork 刀叉；a coat and tie 配有领带的上衣；aim and end 目的；ruth and honesty 真诚</p></div><h2 id="二、形式一致原则-教材-p209-210" tabindex="-1"><a class="header-anchor" href="#二、形式一致原则-教材-p209-210"><span>二、形式一致原则（教材 P209-210）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 二、形式一致原则（教材 P209-210）</p><ul><li><strong>目标</strong>：掌握“形式上单数，谓语就单数”的四种结构：more than one / many a + 单数名词、every/each…and…、one and a half、量词 a series of / a pair of。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>形式一致原则（more than one / many a / each…and… / 量词）</code></li></ul></div><h3 id="二、形式一致原则-教材-p209-210-·-小步学" tabindex="-1"><a class="header-anchor" href="#二、形式一致原则-教材-p209-210-·-小步学"><span>二、形式一致原则（教材 P209-210） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>主谓一致：动词跟谁配合</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>many a / more than one：形式单数意义复数</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>量词结构：a series of / a pair of 看量词，不看后面的名词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出形式一致原则的四条结构，并各举一个谓语用单数的例子。</p><div class="hint-container tip"><p class="hint-container-title">many a / more than one：形式单数意义复数</p><p><strong>句意</strong>：More than one student has made the same mistake. 意思是“不止一个学生犯了同样的错误”；Many a boy likes playing football. 意思是“许多男孩喜欢踢足球”。</p><p><strong>拆解</strong></p><ul><li>More than one student has：虽然意思是“不止一个”（复数意义），但结构上是 one student → 谓语单数</li><li>Many a boy likes：many a + 单数名词，形式单数 → 谓语 likes</li><li>对照：many students like（复数名词配复数谓语）</li><li>口诀：形式一致原则看“形式”，many a / more than one 后接的是单数名词</li></ul><p><strong>语法</strong>：形式一致原则：主语在语法形式上是单数，谓语就用单数，不管它意义上是不是复数。四条：① more than one / many a + 单数名词 → 单数；② every/each/no + 单数名词 + and + every/each/no + 单数名词 → 单数；③ one + 单数名词 + and a half → 单数；④ 量词 + of + 名词：谓语的单复数由量词本身决定（a series of 单、two pairs of 复）。</p><p>正例：Many a boy likes playing football.；More than one student has made the same mistake.；Every boy and every girl in the class is interested in the activity.；One apple and a half is on the table.；A series of lectures is scheduled this semester. 反例：Many a boy like playing football. ×（many a + 单数名词 → 单数谓语）；Two pairs of shoes is under the bed. ×（量词 two pairs 是复数） 适用边界：many a 后面必须跟单数名词；写成 many students 就要用复数谓语（Many students like…）。every…and every… 的并列若改成 every boy and girl 也仍是单数；但若并列的是两个实打实的复数名词（The boys and the girls are…），就用复数。</p><p><strong>口诀</strong>：many a 与 more than one，意思复数、形式单数 —— 看到 many a / more than one，先把眼睛落在“单数名词”这四个字上，谓语跟着形式走。</p></div><div class="hint-container tip"><p class="hint-container-title">量词结构：a series of / a pair of 看量词，不看后面的名词</p><p><strong>句意</strong>：A series of lectures is scheduled this semester. 意思是“本学期安排了一系列讲座”；Two pairs of shoes are under the bed. 意思是“床底下有两双鞋”。</p><p><strong>拆解</strong></p><ul><li>A series of lectures is：中心词是量词 a series（单数）→ 谓语单数</li><li>Two pairs of shoes are：中心词是量词 two pairs（复数）→ 谓语复数</li><li>shoes 本身是复数，但不决定谓语</li><li>This pair of glasses is very expensive：this pair 是单数</li></ul><p><strong>语法</strong>：a series of、a kind of、a piece of、a pair of、a number of 等“量词 + of + 名词”结构中，谓语的单复数以量词（或量词前面的限定词）为准：a series of 单数、two series of 复数、this pair of 单数、two pairs of 复数。</p><p>正例：A series of lectures is scheduled this semester.；Two pairs of shoes are under the bed.；This pair of glasses is very expensive.；Two series of new stamps have been ordered. 反例：Two pairs of shoes is under the bed. ×（量词复数 → 谓语复数）；This pair of glasses are expensive. ×（this pair 单数） 适用边界：这条只在“量词 + of + 名词”结构里成立。若是名词直接作主语（The shoes are…），谓语就跟着名词走。带 s 的量词（series、species）要看清它前面是 a/this 还是 two/these。</p><p><strong>口诀</strong>：量词带 of，谓语看量词 —— 把 of 后面的名词暂时遮住，只用量词判断单复数，判断完再放开。</p></div><p>概念：主语是单数，谓语动词为单数形式；主语若为复数，谓语动词亦为复数形式。</p><ol><li><strong>more than one / many a + 单数名词</strong> → 谓语用单数：</li></ol><p><strong>More than one student has</strong> made the same mistake. 不止一个学生犯了同样的错误。</p><p><strong>Many a boy likes</strong> playing football. 许多男孩喜欢踢足球。 2. <strong>every/each/no + 名词 + and + every/each/no + 名词</strong> → 谓语用单数：</p><p><strong>Every boy and every girl in the class is</strong> interested in the activity.</p><p><strong>Each book and each pen on the desk is</strong> new. 3. <strong>&quot;one + 单数名词 + and a half&quot;（一个半）</strong>→ 谓语用单数：</p><p><strong>One apple and a half is</strong> on the table. 一个半苹果在桌子上。 4. <strong>a series of / a kind of / a piece of / a pair of 等量词</strong> → 谓语的单复数<strong>以量词的单复数</strong>决定：</p><p><strong>A series of</strong> lectures <strong>is</strong> scheduled this semester. 本学期安排了一系列讲座。</p><p><strong>Two pairs of</strong> shoes <strong>are</strong> under the bed. 两双鞋在床底下。</p><h2 id="三、就近原则-教材-p211" tabindex="-1"><a class="header-anchor" href="#三、就近原则-教材-p211"><span>三、就近原则（教材 P211）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 三、就近原则（教材 P211）</p><ul><li><strong>目标</strong>：记住“就近三结构 + 两个句型”：or / either…or / neither…nor / not only…but also 连接并列主语，以及 there be、here be，谓语都跟离它最近的主语一致。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>就近原则（or / either…or / neither…nor / not only…but also / there be）</code></li></ul></div><h3 id="三、就近原则-教材-p211-·-小步学" tabindex="-1"><a class="header-anchor" href="#三、就近原则-教材-p211-·-小步学"><span>三、就近原则（教材 P211） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>主谓一致：动词跟谁配合</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>就近原则：谓语看“邻居”，不看“主心骨”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出就近原则适用的三组连词与两个句型，并各造一个句子。</p><div class="hint-container tip"><p class="hint-container-title">就近原则：谓语看“邻居”，不看“主心骨”</p><p><strong>句意</strong>：Either you or he is wrong. 意思是“要么你错了，要么他错了”；Not only the students but also the teacher likes the movie. 意思是“不仅学生们喜欢这部电影，老师也喜欢”。</p><p><strong>拆解</strong></p><ul><li>Either you or he is wrong：靠近谓语的是 he（单数）→ is；虽有 you，也不影响</li><li>Not only the students but also the teacher likes the movie：靠近谓语的是 the teacher（单数）→ likes</li><li>Nor/mor 一侧的主语才是“邻居”，谓语只看它</li><li>There is a book and two pens on the table：靠近 be 的是 a book（单数）→ is</li></ul><p><strong>语法</strong>：就近原则（也叫“邻近原则”）：谓语动词的单复数与离它最近的主语一致。适用结构：or、either…or…、neither…nor…、not only…but also… 连接的并列主语；there be 句型；here be 句型。</p><p>正例：Either you or he is wrong.；Not only the students but also the teacher likes the movie.；Neither Mike nor I am able to persuade him.；There is a book and two pens on the table. / There are two pens and a book on the table.；Here is a letter and some flowers for you. 反例：Either you or he are wrong. ×（看最近的 he）；Not only the students but also the teacher like the movie. ×（看最近的 teacher）；There are a book and two pens on the table. ×（就近看 a book） 适用边界：就近只在上述结构里成立，不适用于 and 连接的并列主语（Tom and Jerry are…）。there be 句型永远不能换成 there have/has；把并列主语的先后顺序调换，谓语往往会跟着变，这也是自检的办法。</p><p><strong>口诀</strong>：就近看邻居，就远看主干 —— 先判断句子用的是就近还是就远结构，再决定把眼睛停在“最近的主语”还是“最前面的主语”上。</p></div><p>概念：在特定结构中，谓语动词的单复数与<strong>离它最近的主语</strong>保持一致。</p><ol><li>由 <strong>or</strong>（要么）、<strong>either...or...</strong>、<strong>neither...nor...</strong>、<strong>not only...but also...</strong> 连接的并列主语：</li></ol><p><strong>Either you or he is</strong> wrong. 要么你错了，要么他错了。</p><p><strong>Not only</strong> the students <strong>but also the teacher likes</strong> the movie. 不仅学生们喜欢这部电影，老师也喜欢。 2. <strong>there be</strong> 句型：<strong>There is a book</strong> and two pens on the table. / <strong>There are two pens</strong> and a book on the table. 3. <strong>here be</strong> 句型：<strong>Here is a letter</strong> and some flowers for you. 这儿有一封信和一些花给你。</p><h2 id="四、就远原则-教材-p211" tabindex="-1"><a class="header-anchor" href="#四、就远原则-教材-p211"><span>四、就远原则（教材 P211）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 四、就远原则（教材 P211）</p><ul><li><strong>目标</strong>：记住“就远七短语”：with / together with / along with、but / besides / except / in addition to、as well as / including / rather than 都是插入成分，谓语跟它们前面的主语一致。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>就远原则（with / but / as well as 等插入结构）</code></li></ul></div><h3 id="四、就远原则-教材-p211-·-小步学" tabindex="-1"><a class="header-anchor" href="#四、就远原则-教材-p211-·-小步学"><span>四、就远原则（教材 P211） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>主谓一致：动词跟谁配合</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>就远原则：中间的插入语不算主语</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出就远原则的七个（组）短语，并用 as well as 造一个谓语用单数的句子。</p><div class="hint-container tip"><p class="hint-container-title">就远原则：中间的插入语不算主语</p><p><strong>句意</strong>：The teacher with his students is going to the park. 意思是“老师和学生们要去公园”；My mother as well as my sisters is watching TV. 意思是“我妈妈和我的姐妹们正在看电视”。</p><p><strong>拆解</strong></p><ul><li>The teacher with his students is going：with his students 是插入成分，主语仍是 The teacher（单数）→ is</li><li>My mother as well as my sisters is watching：as well as my sisters 同样是插入成分</li><li>判断方法：把插入成分整体删掉，看句子剩下的主语是谁</li><li>Everyone but Jim and Lucy is in support of the idea：but（除了）也属于就远结构</li></ul><p><strong>语法</strong>：就远原则：主语后面跟 with、together with、along with、but、besides、except、in addition to、as well as、including、rather than 等短语时，谓语与这些结构前面的主语一致。这些短语在句法上不是并列主语，而是修饰、补充成分。</p><p>正例：The teacher with his students is going to the park.；Everyone but Jim and Lucy is in support of the idea.；My mother as well as my sisters is watching TV.；Mike, together with his team members, is to take part in the next Olympic Games.；Nobody but Smith and John was in the lab yesterday afternoon. 反例：The teacher with his students are going to the park. ×（被 with 后面的复数带偏）；Mary as well as her friends were walking in the park. ×（主语是 Mary，单数） 适用边界：就远结构里的插入语通常用逗号或介词隔开；若把 with 换成 and，就变成并列主语、谓语要用复数（The teacher and his students are coming.）。两者的区别就在这个连接词上。</p><p><strong>口诀</strong>：就远看主干：with / but / as well as 后面的都不算主语 —— 遇到这些短语，先把它们连同后面的名词用括号括起来，再判断剩下的主语是单还是复。</p></div><p>概念：主语后面跟有 <strong>with, together with, along with, as well as, besides, except, but</strong> 等短语时，谓语动词与<strong>这些结构前面的主语</strong>（较远的那个主语）保持一致。</p><ol><li>3 个&quot;和……一起&quot;：<strong>with, along with, together with</strong></li></ol><p>The teacher <strong>with</strong> his students <strong>is going</strong> to the park. 老师和学生们要去公园。 2. 4 个&quot;除了……&quot;：<strong>but, besides, except, in addition to</strong>（除了、还有）</p><p><strong>Everyone but</strong> Jim and Lucy <strong>is</strong> in support of the idea. 3. <strong>as well as</strong>（和，也）、<strong>including</strong>（包括）、<strong>rather than</strong>（而不是）</p><p>My mother <strong>as well as</strong> my sisters <strong>is watching</strong> TV. 我妈妈和我的姐妹们正在看电视。</p><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 易错清单</p><ul><li><strong>目标</strong>：把本课最容易丢分的几条重新排一遍：集体名词三分法、时间金钱算单数、the number / a number、分数看 of 后、what 从句看表语、one of 与 the only one of 的定语从句。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>one of + 复数名词 + 定语从句的一致</code> <code>主谓一致·意义一致原则（总纲）</code></li></ul></div><h3 id="易错清单-·-小步学" tabindex="-1"><a class="header-anchor" href="#易错清单-·-小步学"><span>易错清单 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>主谓一致：动词跟谁配合</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>one of + 复数名词 + 定语从句：从句看谁？</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>高频易错 10 条速查</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：把“one of 从句复数、the only one of 从句单数”和“the number 单、a number 复”各配一个例句说出来。</p><div class="hint-container tip"><p class="hint-container-title">one of + 复数名词 + 定语从句：从句看谁？</p><p><strong>句意</strong>：Jack is one of the foreign experts who are working in China now. 意思是“杰克是在中国工作的外国专家之一”——定语从句修饰的是 experts（复数），所以从句谓语用 are working。</p><p><strong>拆解</strong></p><ul><li>主句：Jack is one of the foreign experts —— Jack 是“其中之一”</li><li>定语从句 who are working in China 的先行词是 the foreign experts（复数）</li><li>所以从句谓语用复数 are working</li><li>若改成 the only one of the foreign experts，先行词就变成单数的 one → 从句用 is working</li></ul><p><strong>语法</strong>：one of + 复数名词 + 定语从句：从句谓语用复数（先行词是那个复数名词）；the only one of + 复数名词 + 定语从句：从句谓语用单数（先行词被 the only 限定成单数的 one）。</p><p>正例：Jack is one of the foreign experts who are working in China now.（专家中的一位 → 从句复数）；He is the only one of the students who has passed the exam.（唯一一位 → 从句单数） 反例：Jack is one of the experts who is working in China. ×（先行词是 experts）；He is the only one of the students who have passed the exam. ×（唯一一位，从句用单数） 适用边界：判断的关键是定语从句的先行词：one of 后是“许多个”，the only one of 后锁定了“唯一一个”。主句谓语始终跟 one 走（Jack is / He is）。</p><p><strong>口诀</strong>：one of 从句复数，the only one of 从句单数 —— 看“之一”还是“唯一”：之一就配复数，唯一就配单数。</p></div><div class="hint-container tip"><p class="hint-container-title">高频易错 10 条速查</p><p><strong>句意</strong>：The humor they like is different. 意思是“她们喜欢的幽默方式不同”；It is widely believed that a life lived for others is a life worthwhile. 意思是“人们普遍认为，为他人而活的人生是有价值的人生”。</p><p><strong>拆解</strong></p><ul><li>The humor they like is：真主语是 the humor，they like 只是定语从句</li><li>a life lived for others is：真主语是 a life，lived for others 只是过去分词短语作定语</li><li>两句都靠“先找中心词，再看修饰语”拿下</li></ul><p><strong>语法</strong>：本课高频易错 10 条：① 集体名词三分法（people/police/cattle 恒复数；family/team/government 看意义；equipment/furniture 恒单数）；② 时间、金钱、距离、速度复数 → 单数谓语；③ the number of 单 / a number of 复；④ 分数、百分数 + of + 名词看 of 后的名词；⑤ what 从句作主语 + 主系表看表语；⑥ writer and poet 同人用单数、并列整体用单数；⑦ many a / more than one + 单数名词 → 单数谓语；⑧ 就近三结构 + there be / here be；⑨ 就远七短语；⑩ one of 从句复数，the only one of 从句单数。</p><p>正例：The number of primary schools has doubled in the past 50 years.；Neither Jenny&#39;s two brothers nor Tim decides to visit the art exhibition.；The feedback from the customers together with opinions of your manager tells you what to purchase next. 反例：The number of students are large. ×（the number 单数）；So far, a large number of forests has been destroyed. ×（a large number of → 复数） 适用边界：这些口诀只负责“第一反应”，最终还要回到结构本身：先找真主语（剥掉定语、插入语），再看它的意义和形式，最后核对时态与语态。</p><p><strong>口诀</strong>：先剥修饰语，再找真主语；意义看情况，形式看结构 —— 做题时先划掉定语从句和插入语，圈出剩下的中心词，谓语判定的准确率会明显提高。</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>集体名词三分法</strong>：people/police/cattle 恒复数；family/team/government 看意义；equipment/furniture 不可数恒单数。</p></li><li><p><strong>时间/金钱/距离/速度复数 → 单数谓语</strong>（Ten years is...）。</p></li><li><p><strong>the number of 单 / a number of 复</strong>——最高频考点。</p></li><li><p><strong>分数/百分数 + of + 名词</strong>：谓语跟 of 后的名词。</p></li><li><p><strong>what 从句作主语 + 主系表</strong>：谓语跟表语（What we need is/are...）。</p></li><li><p><strong>writer and poet 同人单数</strong>；并列整体（a knife and fork）单数。</p></li><li><p><strong>many a / more than one + 单数名词 → 单数谓语</strong>（形式单数意义复数！）。</p></li><li><p><strong>就近三结构</strong>：or / either...or / neither...nor / not only...but also + there be / here be。</p></li><li><p><strong>就远七短语</strong>：with/together with/along with、but/besides/except/in addition to、as well as/including/rather than。</p></li><li><p><strong>one of + 复数 + 定从 → 从句复数</strong>；<strong>the only one of + 复数 + 定从 → 从句单数</strong>。</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>My favorite fruit ____.</strong></p><ul><li>A. are apples</li><li>B. is apples</li><li>C. is an apple</li><li>D. is apple</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is apples）</strong> —— 开篇易错题（课件已给答案）：主语 fruit（不可数）决定谓语用单数 is；表语 apples 复数不影响谓语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 谓语用 are 是跟着表语 apples 走的：主谓一致只看主语，主语 fruit 不可数 → 单数。干扰点：被表语 apples 是复数带偏。</li><li>B ✅ 主语 fruit 作“水果”讲时不可数，谓语用单数 is；表语 apples 用复数表示“苹果这一类”，不参与主谓一致。课件已给答案。</li><li>C ❌ is 用对了，但 an apple 把“一整类水果”缩成一个苹果，句意变成“我最喜欢的水果是一个苹果”，与常识不符；表语表示类别时用复数。</li><li>D ❌ apple 是可数名词，表示类别要用复数 apples 或 an apple，不能裸用单数形式。干扰点：把可数名词当不可数名词用。</li></ul><p><strong>整句翻译</strong>：我最喜欢的水果是苹果。</p><p><strong>词组</strong>：<code>favorite fruit</code> 最喜欢的水果（fruit 作“水果”讲时不可数）；<code>is apples</code> 表语用复数 apples 表示类别</p><p><strong>对比自测</strong>：做完后对照 quiz:35，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·开篇易错题）：主语 fruit（不可数）决定谓语用单数 is；表语 apples 复数不影响谓语。</p></details><p><strong>Her family ____ much larger than mine. Her family ____ singing and dancing when I called on her last night.</strong></p><ul><li>A. were; was</li><li>B. is; were</li><li>C. is; was</li><li>D. are; were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is; were）</strong> —— 原题为教材 P205 补充练习（笔记补充解析）：第一空强调整体（家庭）→ is；第二空强调家庭成员个体在唱歌跳舞（last night 过去进行）→ were。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 两空都反了：比大小说的是“家庭”这个整体 → 单数 is；第二空说的是一家人各自在唱歌跳舞 → 复数 were。</li><li>B ✅ 第一空 much larger than mine 比的是“家庭”整体 → is；第二空 when I called on her last night 是一家人各自的活动（过去进行时）→ were。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ 第一空对；第二空把家庭当成一个整体，与“一家人有说有唱”的语境不符。干扰点：全程按“整体”处理，忽略语境转换。</li><li>D ❌ 第二空对；第一空把“家庭”当成成员个体，而 much larger than mine 显然是在比两个家庭整体。</li></ul><p><strong>整句翻译</strong>：她家比我家大得多。昨晚我去她家时，她一家人正在唱歌跳舞。</p><p><strong>词组</strong>：<code>much larger than mine</code> 比我家大得多（比较的是“家庭”这个整体）；<code>call on sb.</code> 拜访某人</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·集体名词）：My family is a big one. 我的家庭是个大家庭。 / My family are all music lovers. 我的家人都是音乐爱好者。</p></details><p><strong>The government ____ announced new policies to improve public transportation.</strong></p><ul><li>A. has</li><li>B. have</li><li>C. is having</li><li>D. are having</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（has）</strong> —— 原题为教材 P205 补充练习（笔记补充解析）：government 强调整体，现在完成时 has announced。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ government 强调整体 → 单数；announced 是过去分词，与 has 构成现在完成时。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ have 把政府当成“一群官员”的复数；本课考点取“government 强调整体用单数”。干扰点：按中国学生的直觉把政府理解成“很多人”。</li><li>C ❌ is having 是现在进行时，不能与 announced 这样表示完成的过去分词搭配。</li><li>D ❌ are having 数与时态都不对，同样无法与 announced 组合。</li></ul><p><strong>整句翻译</strong>：政府已经宣布了改善公共交通的新政策。</p><p><strong>词组</strong>：<code>public transportation</code> 公共交通；<code>has announced</code> 已经宣布（现在完成时，announced 是过去分词）</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·集体名词表）：可作单数或复数的集体名词：family、team、class、audience、committee、crew、government、jury 等——强调整体→单数</p></details><p><strong>One hundred and twenty kilometers per hour ____ usually the speed limit for cars on the freeway.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. was</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为教材 P206 补充练习（笔记补充解析）：速度被看作一个整体，用单数（表述一般事实用一般现在时）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把“每小时 120 公里”看成 120 个个体；速度被看作一个整体 → 单数。来源：课件未附答案，本条为笔记补充解析。</li><li>B ✅ 距离、速度、时间、金钱等复数名词作主语时被看作一个整体 → 单数 is；usually 说明这是一般事实，用一般现在时。</li><li>C ❌ were 既是复数形式，又是过去时，与 usually 的一般事实不符。</li><li>D ❌ was 数对了，但过去时与 usually 表示的一般事实冲突。干扰点：看到 was 与 is 都是单数就随手选。</li></ul><p><strong>整句翻译</strong>：高速公路上小汽车限速通常是每小时 120 公里。</p><p><strong>词组</strong>：<code>kilometers per hour</code> 每小时……公里（速度单位）；<code>the speed limit</code> 限速</p><p><strong>对比自测</strong>：做完后对照 quiz:39，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·时间、距离、金钱、重量等复数名词作主语）：通常被看作一个整体，谓语动词用单数：Ten years is a long time. / Five hundred dollars is not a small amount of money.</p></details><p><strong>Economics mainly ____ the study of how a society organizes its money, trade and industry.</strong></p><ul><li>A. refers to</li><li>B. referred of</li><li>C. refer to</li><li>D. refers about</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（refers to）</strong> —— 原题为教材 P206 补充练习（笔记补充解析）：经济学是学科名词用单数；固定搭配 refer to。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Economics 是以 -ics 结尾的学科名词，作主语用单数 → refers；固定搭配 refer to。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ referred of 搭配错误：refer 不与 of 搭配；时态也与“学科定义”这种一般事实不符。</li><li>C ❌ refer to 搭配对，但主语是学科名词，谓语要用单数 refers。干扰点：被 -s 结尾的形式骗了。</li><li>D ❌ refers 数对了，但搭配错误：refer 表示“指的是”时接 to，不接 about。</li></ul><p><strong>整句翻译</strong>：经济学主要研究一个社会如何组织它的金钱、贸易和工业。</p><p><strong>词组</strong>：<code>refer to</code> 指的是，涉及（固定搭配，不与 of / about 搭配）；<code>organize</code> 组织，安排</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·以 -ics 结尾的学科名词作主语）：谓语动词用单数：physics（物理）、mathematics（数学）、economics（经济学）等。</p></details><p><strong>There are nearly 7000 local languages in the world, but only 7% of them ____ in published online material.</strong></p><ul><li>A. were</li><li>B. was</li><li>C. is</li><li>D. are</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（are）</strong> —— 课件附解析：分数/百分数+of+名词/代词作主语，谓语与 of 后面的名词或代词的数保持一致 → them 复数 → are。译：世界上有近 7000 种地方语言，但只有 7% 出现在网上发布的材料中。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ were 是过去时，与前半句 There are 的一般现在时不一致。</li><li>B ❌ was 数与数都不对：7% of them 中 of 后是复数 them。</li><li>C ❌ is 时态对，但谓语要跟 of 后面的 them 一致，而 them 指 local languages（复数）。干扰点：把百分数本身当成不可数。</li><li>D ✅ 分数/百分数 + of + 名词（代词）作主语时，谓语与 of 后面的词一致：them 指 local languages → are.</li></ul><p><strong>整句翻译</strong>：世界上有近 7000 种地方语言，但只有 7% 出现在网上发布的材料中。</p><p><strong>词组</strong>：<code>local languages</code> 地方语言；<code>published online material</code> 网上发布的材料</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·附解析）：分数/百分数+of+名词/代词作主语，谓语与 of 后面的名词或代词的数保持一致 → them 复数 → are。</p></details><p><strong>About 60 percent of the students ____ from the south; the rest of them ____ from the north and foreign countries.</strong></p><ul><li>A. are; is</li><li>B. is; is</li><li>C. is; are</li><li>D. are; are</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（are; are）</strong> —— 原题为教材 P206 补充练习（笔记补充解析）：60 percent of the students 复数 → are；the rest of them 复数 → are。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空对；第二空 the rest of them 中 them 是复数，应用 are。</li><li>B ❌ 两空都错：60 percent of the students 里 of 后是复数 students → are。</li><li>C ❌ 第一空错，理由同 B。</li><li>D ✅ 两空都按“部分 + of + 名词”处理，谓语跟 of 后面一致：students 复数 → are；them 复数 → are。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：大约 60% 的学生来自南方；其余的学生来自北方和外国。</p><p><strong>词组</strong>：<code>60 percent of the students</code> 百分之六十的学生；<code>the rest of them</code> 他们中的其余部分（谓语看 of 后的 them）</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·分数、百分数修饰的名词作主语）：结构：分数/百分数 + of + 名词作主语，谓语与 of 后的名词保持一致。</p></details><p><strong>In many developed countries, the rich ____ richer, the poor poorer, which ____ a social problem.</strong></p><ul><li>A. becomes; are</li><li>B. are becoming; is</li><li>C. became; are</li><li>D. is becoming; is</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（are becoming; is）</strong> —— 原题为教材 P207 练习（笔记补充解析）：the rich/the poor 表一类人 → 复数 are becoming；which 指代前面整个现象 → 单数 is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空 the rich 表一类人 → 复数，不能用 becomes；第二空 which 指代前面整件事 → 单数。</li><li>B ✅ the rich / the poor 表一类人 → 复数 are becoming；which 指代“富人更富、穷人更穷”这一现象 → 单数 is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ became 的时态与“正在变化、日益严重”的语境不符；第二空数也错。</li><li>D ❌ 第一空把 the rich 当成整体单数。干扰点：忘了 the + adj. 表一类人时用复数。</li></ul><p><strong>整句翻译</strong>：在许多发达国家，富人越来越富，穷人越来越穷，这正成为一个社会问题。</p><p><strong>词组</strong>：<code>the rich / the poor</code> 富人 / 穷人（the + 形容词表一类人，谓语用复数）；<code>which 指代整个现象</code> 非限制性定语从句的 which 指代前一分句，谓语用单数</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·the + adj. 作主语）：表示一类人 → 谓语用复数：The rich are not always happy.</p></details><p><strong>What the boy wants ____ a model aeroplane, and what his younger sister wants ____ science books.</strong></p><ul><li>A. are; are</li><li>B. is; is</li><li>C. is; are</li><li>D. are; is</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（is; are）</strong> —— 原题为教材 P207 练习（笔记补充解析）：主系表结构看表语：a model aeroplane 单数 → is；science books 复数 → are。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空 are 与表语 a model aeroplane 不一致；主系表结构里谓语看表语。</li><li>B ❌ 第二空 is 与表语 science books 不一致。</li><li>C ✅ what 主语从句 + 主系表结构：谓语跟表语一致——a model aeroplane 单数 → is；science books 复数 → are。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ 两空都反了。</li></ul><p><strong>整句翻译</strong>：那个男孩想要的是一架模型飞机，他妹妹想要的是科学书。</p><p><strong>词组</strong>：<code>a model aeroplane</code> 一架模型飞机（单数表语）；<code>science books</code> 科学书（复数表语）</p><p><strong>对比自测</strong>：做完后对照 quiz:23，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·what 引导的主语从句）：若主句为主系表结构，谓语单复数取决于表语名词的单复数：What we need are good teachers. / What we need is a good teacher.</p></details><p><strong>The number of primary schools in the rural areas ____ doubled in the past 50 years.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. have</li><li>D. has</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（has）</strong> —— 原题为教材 P207 练习（笔记补充解析）：the number 单数；in the past 50 years 与完成时连用 → has doubled。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把 the number of 当成了复数结构；另外 doubled 是过去分词，助动词应用 has。</li><li>B ❌ is doubled 的时态不成立：in the past 50 years 要求现在完成时，doubled 需要助动词 has。</li><li>C ❌ have 的数不对：the number（数目）是单数 → has。干扰点：看到 of 后面的复数名词就用复数助动词。</li><li>D ✅ the number of（……的数目）作主语用单数；in the past 50 years 是现在完成时标志 → has doubled。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：过去 50 年里，农村地区小学的数量翻了一番。</p><p><strong>词组</strong>：<code>the number of</code> ……的数目（谓语用单数）；<code>in the past 50 years</code> 在过去 50 年里（与完成时连用）</p><p><strong>对比自测</strong>：做完后对照 quiz:10，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·a number of / the number of）：the number of + 复数名词：“……的数目”（单数意义），谓语用单数：The number of students in our school is about 2000.</p></details><p><strong>The number of people who were invited to the party ____ fifty, but a number of them ____ absent for different reasons.</strong></p><ul><li>A. were; was</li><li>B. was; was</li><li>C. was; were</li><li>D. were; were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（was; were）</strong> —— 原题为教材 P207 练习（笔记补充解析）：the number of people → was；a number of them → were。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 两空都反了。</li><li>B ❌ 第一空对；第二空 a number of them 表示“他们中的许多人” → 复数 were。干扰点：同一句里两个 number 结构被当成同一个。</li><li>C ✅ the number of people（人数）→ 单数 was；a number of them（许多人）→ 复数 were。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ 第一空错，理由同 B。</li></ul><p><strong>整句翻译</strong>：被邀请参加聚会的宾客人数是五十人，但他们中许多人因各种原因没有到场。</p><p><strong>词组</strong>：<code>the number of people</code> 人数（单数）；<code>a number of them</code> 他们中的许多人（复数）</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·口诀卡）：the number 单，a number 复</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：Physics ________ (be) not easy to understand.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：-ics 结尾学科名词作主语用单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把学科名词当复数；-ics 结尾的学科名是单数概念。</li><li>B ✅ -ics 结尾的学科名词作主语用单数 → is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 既是复数又是过去时，与“学科特点”这一般事实不符。</li><li>D ❌ be 动词原形不能单独作谓语；陈述句谓语必须有时态和人称。</li></ul><p><strong>整句翻译</strong>：物理并不容易理解。</p><p><strong>词组</strong>：<code>be easy to understand</code> 容易理解（不定式用主动表被动）；<code>physics</code> 物理（-ics 结尾的学科名词，谓语用单数）</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·例句）：Physics is not an easy subject for some students.</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：Nothing ________ (be) impossible.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. am</li><li>D. were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：nothing 是不定代词作主语用单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 是复数形式，nothing 是不定代词，作主语用单数。</li><li>B ✅ nothing、everyone、somebody 等不定代词作主语时谓语用单数；这是一句格言，用一般现在时 is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ am 只用于主语 I，nothing 不能配 am。</li><li>D ❌ were 既是复数又是过去时，都不对。</li></ul><p><strong>整句翻译</strong>：没有什么是不可能的。</p><p><strong>词组</strong>：<code>nothing is impossible</code> 没有不可能的事（不定代词作主语用单数）</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·不定代词作主语）：everyone, everybody, someone, somebody, anyone, anybody, no one, nobody 等作主语时，谓语动词用单数。</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：Ten pounds ________ (be) missing from the box.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. have been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：金钱被看作一个整体用单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把“十镑钱”看成十个个体；金额被看作一个整体 → 单数。</li><li>B ✅ Ten pounds 表示“一笔钱”，看作一个整体 → 单数 is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 复数 + 过去时：句子没有过去时间的依据。</li><li>D ❌ have been 是复数助动词，句意也不需要完成时。</li></ul><p><strong>整句翻译</strong>：盒子里少了十镑钱。</p><p><strong>词组</strong>：<code>ten pounds</code> 十英镑（金额看作一个整体）；<code>be missing</code> 不见了，缺少</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·时间、金钱等作主语）：Five hundred dollars is not a small amount of money. 五百美元不是一笔小数目。</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：The number of the students in our school ________ quite large and a number of teachers ________ hard.</strong></p><ul><li>A. is; work</li><li>B. are; works</li><li>C. is; works</li><li>D. are; work</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（is; work）</strong> —— 原题为填空题，笔记答案 is; work：the number 单数；a number of 复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ the number of（数目）→ 单数 is；a number of（许多）→ 复数 work。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ 两空都反了。</li><li>C ❌ 第二空错：a number of teachers 是复数主语 → work。</li><li>D ❌ 第一空错：the number（数目）是单数 → is。</li></ul><p><strong>整句翻译</strong>：我们学校学生的数目相当大，许多老师工作很努力。</p><p><strong>词组</strong>：<code>the number of the students</code> 学生的数目（单数）；<code>a number of teachers</code> 许多老师（复数）</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·a number of / the number of 表）：a number of + 复数名词（“许多……”，复数意义）→ 复数；the number of + 复数名词（“的数目”，单数意义）→ 单数。</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：The disabled ________ well taken care of in this country.</strong></p><ul><li>A. is</li><li>B. are</li><li>C. was</li><li>D. has been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（are）</strong> —— 原题为填空题，笔记答案 are：the disabled 表一类人 → 复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is 是单数：the disabled 表一类人 → 复数。</li><li>B ✅ the + adj.（the disabled）表一类人 → 复数 are；被动结构 be taken care of 需要 be 的复数形式。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ was 既是复数又是过去时，句子描述的是现在的一般情况。</li><li>D ❌ has been 用单数助动词，与表一类人的复数主语不一致。</li></ul><p><strong>整句翻译</strong>：在这个国家，残疾人得到了很好的照顾。</p><p><strong>词组</strong>：<code>the disabled</code> 残疾人（the + adj. 表一类人）；<code>take care of</code> 照顾（被动式 be taken care of）</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·the + adj. 作主语）：表示一类人 → 谓语用复数：The rich are not always happy.</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：The new ________ certain to replace the old.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. have been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：the + adj. 表抽象概念（&quot;新事物必将取代旧事物&quot;）→ 单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把 the new 当成一类人；这里 the new 指的是“新事物”这一抽象概念 → 单数。干扰点：把 the + adj. 一律当复数。</li><li>B ✅ the + adj. 表抽象概念（新事物）→ 单数 is；be certain to replace 表示“必将会取代”。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 复数 + 过去时，都不对。</li><li>D ❌ have been 用复数助动词，且句意不需要完成时。</li></ul><p><strong>整句翻译</strong>：新事物必然会取代旧事物。</p><p><strong>词组</strong>：<code>the new / the old</code> 新的（事物）/ 旧的（事物）（此处表抽象概念）；<code>be certain to do</code> 一定会做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·the + adj. 作主语）：表示一类人 → 谓语用复数；表示抽象概念 → 谓语用单数。</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：The rest of the workers ________ still very tired.</strong></p><ul><li>A. is</li><li>B. are</li><li>C. was</li><li>D. has been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（are）</strong> —— 原题为填空题，笔记答案 are：the rest of + 复数名词 → 复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is 是单数：the rest of + 复数名词 → 复数。</li><li>B ✅ the rest of the workers：谓语跟 of 后的 workers（复数）一致 → are。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ was 数与数都不对：句子描述的是现在的情况。</li><li>D ❌ has been 用单数助动词，与复数主语不一致。</li></ul><p><strong>整句翻译</strong>：其余的工人仍然很疲惫。</p><p><strong>词组</strong>：<code>the rest of the workers</code> 其余的工人（谓语看 of 后的 workers）；<code>be tired</code> 疲惫</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·分数、百分数修饰的名词作主语）：Part of the students have gone home.</p></details><p><strong>填空转选择（教材 P208，笔记补充解析）：His family ________ all sitting in the sofa watching TV.</strong></p><ul><li>A. is</li><li>B. are</li><li>C. was</li><li>D. has been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（are）</strong> —— 原题为填空题，笔记答案 are：family 此处强调成员，有 all 提示 → 复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is 把家庭当成一个整体；句中 all 明摆着在说“家人各自”。</li><li>B ✅ all 提示强调家庭成员 → 复数 are。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ was 是单数形式，与强调成员的复数主语不符；句子的语境也是现在。</li><li>D ❌ has been 用单数助动词，与表成员的复数主语不一致。</li></ul><p><strong>整句翻译</strong>：他的家人全都坐在沙发上看着电视。</p><p><strong>词组</strong>：<code>all sitting in the sofa</code> 全都坐在沙发上（all 提示强调成员）；<code>watch TV</code> 看电视</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·集体名词）：My family are all music lovers. 我的家人都是音乐爱好者。</p></details><p><strong>Each of the students ____ responsible for finishing the project in time.</strong></p><ul><li>A. has</li><li>B. have</li><li>C. are</li><li>D. is</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（is）</strong> —— 原题为教材 P209-210 练习（笔记补充解析）：each of + 复数名词 → 谓语单数；此处需 be 动词 is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 空格后面是形容词 responsible，需要 be 动词而不是 have；而且 has 与单数主语搭配才成立，句式上也不通。</li><li>B ❌ 同上：be responsible for 需要 be 动词；have 无论单复数都不对。</li><li>C ❌ are 是复数：each of + 复数名词作主语，谓语用单数。干扰点：看到 students 就用复数。</li><li>D ✅ each of + 复数名词 → 谓语单数；be responsible for 需要 be 动词 → is。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：每个学生都有责任按时完成这个项目。</p><p><strong>词组</strong>：<code>each of + 复数名词</code> ……中的每一个（作主语时谓语用单数）；<code>be responsible for</code> 对……负责</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·形式一致）：each of + 复数名词 → 谓语单数</p></details><p><strong>Each child and adult ____ some kind of trouble in their lives.</strong></p><ul><li>A. has</li><li>B. have</li><li>C. to have</li><li>D. having</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（has）</strong> —— 原题为教材 P209-210 练习（笔记补充解析）：each...and each... 结构 → 单数；have 为实义动词。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ each…and… 结构（every/each/no + 名词 + and + every/each/no + 名词）作主语 → 单数；此处 have 是实义动词“有” → has。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ have 是复数形式，与 each…and… 的单数要求不符。干扰点：看到 and 就用复数。</li><li>C ❌ to have 是不定式，不能作谓语。</li><li>D ❌ having 是非谓语形式，句子会没有谓语。</li></ul><p><strong>整句翻译</strong>：每个孩子和大人在生活中都会遇到某种麻烦。</p><p><strong>词组</strong>：<code>each child and adult</code> 每个孩子和大人（each…and… 结构 → 单数谓语）；<code>some kind of trouble</code> 某种麻烦</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·形式一致原则）：every/each/no + 名词 + and + every/each/no + 名词 → 谓语用单数：Every boy and every girl in the class is interested in the activity.</p></details><p><strong>We each ____ strong points and each of us, on the other hand, ____ weak points.</strong></p><ul><li>A. have; have</li><li>B. has; have</li><li>C. has; has</li><li>D. have; has</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（have; has）</strong> —— 课件附解析：第一个空前的 each 作同位语，主语是 we，第一个空用复数；后半句 each of + 名词复数作主语，谓语用单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空对；第二空 each of us 是主语 → 单数 has。</li><li>B ❌ 第一空错：句首的 each 是同位语，真正的主语是 We。</li><li>C ❌ 第一空错，理由同 B。</li><li>D ✅ 第一空 each 作同位语，主语 We → 复数 have；第二空 each of us 作主语 → 单数 has。</li></ul><p><strong>整句翻译</strong>：我们每个人都有优点，另一方面，我们每个人也都有缺点。</p><p><strong>词组</strong>：<code>strong points</code> 优点；<code>each of us</code> 我们每个人（作主语 → 单数谓语）</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·附解析）：第一个空前的 each 作同位语，主语是 we，第一个空用复数；后半句 each of + 名词复数作主语，谓语用单数。</p></details><p><strong>Many a student in this college ____ a walk on campus after dinner. But many students in my elder brother’s school ____ computer games in the dormitory.</strong></p><ul><li>A. takes; play</li><li>B. take; play</li><li>C. took; play</li><li>D. have taken; have played</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（takes; play）</strong> —— 原题为教材 P209-210 练习（笔记补充解析）：many a + 单数名词 → takes；many students 复数 → play。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ many a + 单数名词 → 单数谓语 takes；many students（复数名词）→ 复数谓语 play。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ 第一空错：many a student 形式上是单数。</li><li>C ❌ took 是一般过去时，而句子描述的是习惯（after dinner）→ 一般现在时。</li><li>D ❌ have taken / have played 是现在完成时，与描述习惯的语境不符。</li></ul><p><strong>整句翻译</strong>：这所大学里许多学生晚饭后都会在校园里散步。但我哥哥学校里许多学生却在宿舍里打电脑游戏。</p><p><strong>词组</strong>：<code>many a student</code> 许多学生（形式单数 → 谓语单数）；<code>take a walk</code> 散步</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·形式一致原则）：more than one / many a + 单数名词 → 谓语用单数：Many a boy likes playing football.</p></details><p><strong>填空转选择（教材 P210，笔记补充解析）：What surprised me most ________ (be) his attitude towards his study.</strong></p><ul><li>A. is</li><li>B. was</li><li>C. were</li><li>D. are</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（was）</strong> —— 原题为填空题，笔记答案 was：主语从句表单一事件，主句过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is 与主句 surprised 的过去时不呼应：描述的是过去发生的事。</li><li>B ✅ what 主语从句表一件事 → 单数；主句时态与从句保持一致（surprised 是过去）→ was。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 是复数形式。</li><li>D ❌ are 既是复数又是现在时，都不对。</li></ul><p><strong>整句翻译</strong>：最让我吃惊的是他对待学习的态度。</p><p><strong>词组</strong>：<code>What surprised me most</code> 最让我吃惊的事（主语从句）；<code>his attitude towards his study</code> 他对学习的态度</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·what 引导的主语从句）：从句作主语，谓语动词常用单数</p></details><p><strong>填空转选择（教材 P210，笔记补充解析）：War and peace ________ (be) a constant theme in history.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. have been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：War and peace 战争与和平为整体抽象概念。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把 war 和 peace 当成两样并列的东西；这里它们是合成一体的话题 → 单数。干扰点：看到 and 就用复数。</li><li>B ✅ 并列主语表同一概念、整体（战争与和平这一主题）→ 单数 is；陈述常态用一般现在时。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 复数 + 过去时，都不对。</li><li>D ❌ have been 用复数助动词，且句意不需要完成时。</li></ul><p><strong>整句翻译</strong>：战争与和平是历史中一个恒定的主题。</p><p><strong>词组</strong>：<code>a constant theme</code> 一个恒定的主题；<code>War and peace</code> 战争与和平（整体抽象概念）</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·并列结构表整体概念）：并列结构表整体概念（谓语用单数）：iron and steel 钢铁；law and order 治安；bread and butter 黄油面包；a watch and chain 一块带链的表；a knife and fork 刀叉</p></details><p><strong>填空转选择（教材 P210，笔记补充解析）：This pair of glasses ________ (be) very expensive.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. were</li><li>D. have been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为填空题，笔记答案 is：a pair of 类量词，this pair 单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 跟着 glasses（复数）走；这类“量词 + of + 名词”结构里谓语由量词决定。干扰点：眼镜在英语里总是复数形式，容易误判。</li><li>B ✅ a pair of 类量词结构：谓语以量词为准，this pair 是单数 → is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ were 复数 + 过去时，都不对。</li><li>D ❌ have been 的助动词形式不对（单数该用 has been），句意也不需要完成时。</li></ul><p><strong>整句翻译</strong>：这副眼镜很贵。</p><p><strong>词组</strong>：<code>this pair of glasses</code> 这副眼镜（量词 this pair 是单数）；<code>expensive</code> 昂贵的</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·形式一致原则）：a series of / a kind of / a piece of / a pair of 等量词 → 谓语的单复数以量词的单复数决定</p></details><p><strong>填空转选择（教材 P210，笔记补充解析）：Two series of new stamps ________ (have) been ordered.</strong></p><ul><li>A. has</li><li>B. have</li><li>C. is</li><li>D. was</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（have）</strong> —— 原题为填空题，笔记答案 have：two series 复数量词 → 复数谓语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has 是单数助动词：量词是 two series（复数）。</li><li>B ✅ 量词 two series 是复数 → 助动词用 have；been ordered 构成完成时被动。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ is been ordered 不成立：完成时的被动要用 have/has been done。</li><li>D ❌ was been ordered 同样不成立，且时态也不对。</li></ul><p><strong>整句翻译</strong>：两套新邮票已经被订购了。</p><p><strong>词组</strong>：<code>a series of</code> 一系列（量词，单复数决定谓语）；<code>have been ordered</code> 已被订购（现在完成时被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·形式一致原则）：A series of lectures is scheduled this semester. / Two pairs of shoes are under the bed.</p></details><p><strong>There ____ pen, a few envelopes and some paper on the desk.</strong></p><ul><li>A. are</li><li>B. were</li><li>C. is</li><li>D. have</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（is）</strong> —— 原题为教材 P211 练习（笔记补充解析）：就近原则看 pen（单数）→ is；there be 句型不能选 have。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 没有就近：离 be 最近的 a pen 是单数。干扰点：把后面的 a few envelopes 当成第一个主语。</li><li>B ❌ were 既是复数又是过去时；句子没有过去时间依据。</li><li>C ✅ there be 句型用就近原则：离 be 最近的 pen 是单数 → is。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ there have 不成立：表示“有”的 there be 句型不能用 have 替换。</li></ul><p><strong>整句翻译</strong>：桌上有一支钢笔、几个信封和一些纸。</p><p><strong>词组</strong>：<code>there be 句型</code> 表示“有”，谓语与最近的主语一致，不能换成 have；<code>a few envelopes</code> 几个信封</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就近原则）：there be 句型：There is a book and two pens on the table. / There are two pens and a book on the table.</p></details><p><strong>Either my parents or my elder brother ____ going to water the garden.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. has</li><li>D. have</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为教材 P211 练习（笔记补充解析）：either...or 就近 my elder brother 单数 → is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 看了 my parents（复数），但就近的是 my elder brother（单数）。</li><li>B ✅ either…or 就近原则：与谓语最近的主语 my elder brother 是单数 → is。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ has 不构成 be going to 结构，而且数是单数、结构缺失，两处都不对。</li><li>D ❌ have 同上：be going to 需要 be 动词，不能用 have。</li></ul><p><strong>整句翻译</strong>：要么我父母去给花园浇水，要么我哥哥去。</p><p><strong>词组</strong>：<code>either…or…</code> 要么……要么……（就近原则）；<code>be going to do</code> 将要/打算做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就近原则）：Either you or he is wrong. 要么你错了，要么他错了。</p></details><p><strong>Not only I but also Jenny and Rose ____ fond of swimming and fishing.</strong></p><ul><li>A. am</li><li>B. is</li><li>C. be</li><li>D. are</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（are）</strong> —— 原题为教材 P211 练习（笔记补充解析）：not only...but also 就近 Jenny and Rose 复数 → are。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ am 盯着句首的 I；就近的是 but also 后的 Jenny and Rose（复数）。</li><li>B ❌ is 是单数，与就近的复数主语不符。</li><li>C ❌ be 动词原形不能作谓语。</li><li>D ✅ not only…but also 就近原则：与谓语最近的主语 Jenny and Rose 是复数 → are。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：不仅我喜欢游泳和钓鱼，珍妮和罗斯也喜欢。</p><p><strong>词组</strong>：<code>not only…but also…</code> 不仅……而且……（就近原则）；<code>be fond of</code> 喜欢</p><p><strong>对比自测</strong>：做完后对照 quiz:30，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就近原则）：Not only the students but also the teacher likes the movie.</p></details><p><strong>Neither Mike nor I ____ able to persuade his grandfather to attend the wedding.</strong></p><ul><li>A. am</li><li>B. are</li><li>C. are to be</li><li>D. is</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（am）</strong> —— 原题为教材 P211 练习（笔记补充解析）：neither...nor 就近 I → am。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ neither…nor 就近原则：与谓语最近的主语是 I → 用 am。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ are 是复数，与 I 不搭（I 配 am）。</li><li>C ❌ are to be 把 be able to 的结构改错，数与结构都不对。</li><li>D ❌ is 是第三人称单数形式，不能与 I 搭配。</li></ul><p><strong>整句翻译</strong>：迈克和我都没能说服他祖父参加婚礼。</p><p><strong>词组</strong>：<code>neither…nor…</code> 既不……也不……（就近原则）；<code>be able to do</code> 能够做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就近原则）：either...or / neither...nor / not only...but also 连接的并列主语——就近一致</p></details><p><strong>Mary as well as her friends ____ in the park when her mom called her.</strong></p><ul><li>A. was walking</li><li>B. were walking</li><li>C. walks</li><li>D. walk</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（was walking）</strong> —— 原题为教材 P211 练习（笔记补充解析）：as well as 就远，主语 Mary 单数；when her mom called 过去背景 → 过去进行 was walking。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ as well as 就远：谓语跟前面的主语 Mary（单数）一致；when her mom called 是过去背景，“正在散步”用过去进行 → was walking。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ were walking 被 as well as her friends 带偏，误把主语当成复数。干扰点：把插入成分当并列主语。</li><li>C ❌ walks 是一般现在时，与 when her mom called 的过去背景冲突。</li><li>D ❌ walk 既是复数又是一般现在时，两处都不对。</li></ul><p><strong>整句翻译</strong>：她妈妈给她打电话时，玛丽和朋友们正在公园里散步。</p><p><strong>词组</strong>：<code>as well as</code> 和，也（就远结构，谓语跟前面的主语一致）；<code>when her mom called her</code> 她妈妈给她打电话时（过去时间背景）</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就远原则）：My mother as well as my sisters is watching TV. 我妈妈和我的姐妹们正在看电视。</p></details><p><strong>Everyone in this town, including children and old people, ____ in for Tai Chi.（go in for: 对……感兴趣）</strong></p><ul><li>A. go</li><li>B. goes</li><li>C. going</li><li>D. to go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（goes）</strong> —— 原题为教材 P211 练习（笔记补充解析）：including 就远，主语 everyone 单数；表述一般习惯用一般现在时 → goes。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ go 的数不对：主语是 everyone（单数），including 只是插入成分。</li><li>B ✅ including 就远：谓语跟前面的主语 everyone（单数）一致；表述一般习惯用一般现在时 → goes。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ going 是非谓语形式，句子会没有谓语。</li><li>D ❌ to go 是不定式，同样不能作谓语。</li></ul><p><strong>整句翻译</strong>：这个镇上的每个人，包括孩子和老人，都喜欢打太极。</p><p><strong>词组</strong>：<code>including</code> 包括（就远结构，谓语跟前面的主语一致）；<code>go in for</code> 对……感兴趣，喜欢</p><p><strong>对比自测</strong>：做完后对照 quiz:31，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就远原则）：as well as（和，也）、including（包括）、rather than（而不是）——谓语与这些结构前面的主语保持一致</p></details><p><strong>Mike, together with his team members, ____ to take part in the next Olympic Games.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. be</li><li>D. am</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 原题为教材 P211 练习（笔记补充解析）：together with 就远，Mike 单数 → is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 被 together with his team members 带偏。干扰点：把插入成分当成并列主语。</li><li>B ✅ together with 就远：谓语跟 Mike（单数）→ is；be to do 表示按安排要做的事。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ be 动词原形不能作谓语。</li><li>D ❌ am 只用于主语 I，人称不对。</li></ul><p><strong>整句翻译</strong>：迈克和他的队员们将要参加下一届奥运会。</p><p><strong>词组</strong>：<code>together with</code> 和……一起（就远结构）；<code>take part in</code> 参加</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就远原则）：The teacher with his students is going to the park. 老师和学生们要去公园。</p></details><p><strong>Nobody but Smith and John ____ in the lab yesterday afternoon.</strong></p><ul><li>A. were</li><li>B. had been</li><li>C. is</li><li>D. was</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（was）</strong> —— 原题为教材 P211 练习（笔记补充解析）：but 就远，nobody 单数；yesterday afternoon 过去时 → was。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ were 被 but 后面的复数主语带偏；but（除了）是插入结构，主语仍是 nobody（单数）。</li><li>B ❌ had been 是过去完成时，句中缺少“更早”的参照点。</li><li>C ❌ is 时态不对：yesterday afternoon 是过去时间。</li><li>D ✅ but（除了）就远：谓语跟前面的 nobody（单数）一致；yesterday afternoon 是过去 → was。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：昨天下午除了史密斯和约翰，没人在实验室里。</p><p><strong>词组</strong>：<code>nobody but</code> 除了……没有别人（but 属于就远结构）；<code>yesterday afternoon</code> 昨天下午（过去时间标志）</p><p><strong>对比自测</strong>：做完后对照 quiz:33，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就远原则）：Everyone but Jim and Lucy is in support of the idea.</p></details><p><strong>【24重庆真题】Susan and Jean like humor, but the humor they like ____ different.</strong></p><ul><li>A. are</li><li>B. is</li><li>C. was</li><li>D. were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（is）</strong> —— 笔记补充解析：humor 不可数单数；一般现在时表客观 → is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 把 humor 当复数；humor 是不可数名词，主语是 the humor → 单数。</li><li>B ✅ 真主语是 the humor（they like 只是修饰它的定语从句），humor 不可数 → 单数 is；前半句 like 是一般现在时，时态一致。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ was 是过去时，与前半句 like 的一般现在时不一致。</li><li>D ❌ were 复数 + 过去时，都不对。</li></ul><p><strong>整句翻译</strong>：苏珊和琼喜欢幽默，但她们喜欢的幽默方式不同。</p><p><strong>词组</strong>：<code>the humor they like</code> 她们喜欢的那种幽默（they like 是定语从句，真主语是 the humor）；<code>be different</code> 不同</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：humor 不可数单数；一般现在时表客观 → is。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>【24湖南真题】It is widely believed that a life lived for others ____ a life worthwhile.（人们普遍认为，为他人而活的人生是有价值的人生。）</strong></p><ul><li>A. is</li><li>B. are</li><li>C. were</li><li>D. was</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（is）</strong> —— 笔记补充解析：主语 a life 单数 → is。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语从句里的主语是 a life（lived for others 只是修饰语）→ 单数 is。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ are 被 lived for others 里的复数语感带偏；真正的中心词是 a life。</li><li>C ❌ were 复数 + 过去时，都不对。</li><li>D ❌ was 是过去时，与主句 It is widely believed 的一般现在时不一致。</li></ul><p><strong>整句翻译</strong>：人们普遍认为，为他人而活的人生是有价值的人生。</p><p><strong>词组</strong>：<code>It is widely believed that…</code> 人们普遍认为……（被动句型）；<code>a life lived for others</code> 为他人而活的人生（lived for others 是过去分词短语作定语）</p><p><strong>对比自测</strong>：做完后对照 quiz:35，比较两题的判断依据</p><p><strong>原文定位</strong>（课件解析（原题 why））：主语 a life 单数 → is。来源：课件未附答案，本条为笔记补充解析。</p></details><p><strong>综合练习 1：Jack is one of the foreign experts who ____ in China now.</strong></p><ul><li>A. worked</li><li>B. is working</li><li>C. are working</li><li>D. has been working</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（are working）</strong> —— 课件附解析：one of + 复数名词 + 定语从句结构中，从句谓语用复数形式（若 the only one of + 复数名词 + 定语从句，从句谓语用单数）；now 提示进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worked 是一般过去时，与 now 冲突。</li><li>B ❌ is working 用单数：定语从句的先行词是复数 experts。干扰点：以为从句修饰 Jack。</li><li>C ✅ one of + 复数名词 + 定语从句：从句谓语用复数 are working；now 提示进行时。</li><li>D ❌ has been working 用单数助动词，先行词是复数 experts；也不如 are working 贴合 now。</li></ul><p><strong>整句翻译</strong>：杰克是在中国工作的外国专家之一。</p><p><strong>词组</strong>：<code>one of + 复数名词 + 定语从句</code> ……之一（从句谓语用复数）；<code>foreign experts</code> 外国专家</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·附解析）：one of + 复数名词 + 定语从句结构中，从句谓语用复数形式（若 the only one of + 复数名词 + 定语从句，从句谓语用单数）；now 提示进行时。</p></details><p><strong>综合练习 2：Whether I will go or stay ____ on the evaluation of my mother’s health condition by the doctor.</strong></p><ul><li>A. depend</li><li>B. dependent</li><li>C. depends</li><li>D. depending</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（depends）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：whether 主语从句 → 单数；depend on 固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ depend 是复数形式：whether 主语从句作主语 → 单数。干扰点：从句里出现了 I，就误以为主语是 I。</li><li>B ❌ dependent 是形容词，句子会缺谓语。</li><li>C ✅ whether 引导的主语从句作主语 → 单数 depends；depend on 是固定搭配。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ depending 是非谓语形式，不能作谓语。</li></ul><p><strong>整句翻译</strong>：我走还是留，取决于医生对我母亲健康状况的评估。</p><p><strong>词组</strong>：<code>whether 主语从句</code> whether 引导的从句作主语（谓语用单数）；<code>depend on</code> 取决于（固定搭配）</p><p><strong>对比自测</strong>：做完后对照 quiz:23，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·what 引导的主语从句）：从句作主语，谓语动词常用单数</p></details><p><strong>综合练习 3：I don’t know what you think, but three weeks ____ already enough for me to finish the work.</strong></p><ul><li>A. is</li><li>B. are</li><li>C. was</li><li>D. were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（is）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：three weeks 时间整体 → 单数。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ three weeks 表示一段时间，被看作一个整体 → 单数 is。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ are 把“三周时间”当成三个个体。</li><li>C ❌ was 是过去时，与前句 I don&#39;t know 的现在语境不符。</li><li>D ❌ were 复数 + 过去时，都不对。</li></ul><p><strong>整句翻译</strong>：我不知道你怎么想，但三个星期对我来说已经足够完成这项工作了。</p><p><strong>词组</strong>：<code>three weeks</code> 三个星期（一段时间，看作整体）；<code>be enough for sb.</code> 对某人来说足够</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·时间复数名词作主语）：Ten years is a long time. 十年是很长的一段时间。</p></details><p><strong>综合练习 4：As a result of the serious flood, ____ of the buildings in the area ____ repairing.</strong></p><ul><li>A. two-third; need</li><li>B. two-thirds; needs</li><li>C. two-thirds; need</li><li>D. second-three; need</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（two-thirds; need）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：分数表达 two-thirds 分子&gt;1 分母加 s；of the buildings 复数 → need。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ two-third 分数写法错：分子大于 1 时分母要用复数 two-thirds。</li><li>B ❌ 分数写法对，但 needs 用单数：of 后面的 buildings 是复数 → need。</li><li>C ✅ two-thirds（分子大于 1，分母加 s）+ of the buildings（复数）→ need；need doing 主动表被动。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ second-three 不是英语的分数表达（基数词与序数词的位置与形式都错）。</li></ul><p><strong>整句翻译</strong>：由于这场严重的洪水，该地区三分之二的建筑都需要修缮。</p><p><strong>词组</strong>：<code>two-thirds of the buildings</code> 三分之二的建筑（分数 + of + 名词）；<code>need repairing</code> 需要修缮（need doing 主动表被动）</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·分数、百分数修饰的名词作主语）：分数/百分数 + of + 名词作主语，谓语与 of 后的名词保持一致</p></details><p><strong>综合练习 5：So far, a large number of forests ____ because of air pollution and water pollution.</strong></p><ul><li>A. has been destroyed</li><li>B. destroy</li><li>C. have destroyed</li><li>D. have been destroyed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（have been destroyed）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：a number of 复数 + so far 完成时 + 森林被毁被动 → have been destroyed。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has been destroyed 用单数助动词：a large number of 是“许多” → 复数。</li><li>B ❌ destroy 是主动的一般现在时，语态与时态都不对。</li><li>C ❌ have destroyed 是主动语态：森林是“被”毁的。</li><li>D ✅ a number of + 复数名词 → 复数谓语；so far → 现在完成时；森林是承受者 → 被动：have been destroyed。来源：课件未附答案，本条为笔记补充解析。</li></ul><p><strong>整句翻译</strong>：到目前为止，由于空气污染和水污染，大量森林已被毁。</p><p><strong>词组</strong>：<code>so far</code> 到目前为止（现在完成时标志）；<code>a large number of forests</code> 大量森林（a number of → 复数谓语）</p><p><strong>对比自测</strong>：做完后对照 quiz:10，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·a number of / the number of）：a number of + 复数名词：“许多……”（复数意义）→ 复数</p></details><p><strong>综合练习 6：The feedback from the customers together with opinions of your manager ____ you what to purchase next.</strong></p><ul><li>A. tell</li><li>B. tells</li><li>C. have told</li><li>D. told</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（tells）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：together with 就远，主语 feedback 不可数单数 → tells。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tell 被 together with opinions of your manager 带偏；主语是 feedback（不可数）→ 单数。</li><li>B ✅ together with 就远：谓语跟主语 feedback 一致；feedback 不可数 → 单数 tells。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ have told 用复数助动词 + 完成时，与主语和语境都不符。</li><li>D ❌ told 是过去时，而句子陈述的是一般事理（反馈会告诉你……）。</li></ul><p><strong>整句翻译</strong>：顾客的反馈加上你经理的意见，会告诉你接下来该采购什么。</p><p><strong>词组</strong>：<code>feedback</code> 反馈（不可数名词）；<code>together with</code> 连同……一起（就远结构）</p><p><strong>对比自测</strong>：做完后对照 quiz:33，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就远原则）：The teacher with his students is going to the park.</p></details><p><strong>综合练习 7：Neither Jenny’s two brothers nor Tim ____ to visit the art exhibition next Friday because all of them will be busy with their classes then.</strong></p><ul><li>A. decide</li><li>B. decided</li><li>C. decides</li><li>D. to decide</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（decides）</strong> —— 原题为主谓一致综合练习（笔记补充解析）：neither...nor 就近 Tim 三单 → decides。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ decide 是复数形式：就近的是 Tim（第三人称单数）。</li><li>B ❌ decided 是过去时，与 next Friday 的将来语境冲突。</li><li>C ✅ neither…nor 就近原则：与谓语最近的 Tim 是第三人称单数 → decides；decide to do sth. 固定搭配。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ to decide 是不定式，不能作谓语。</li></ul><p><strong>整句翻译</strong>：珍妮的两个哥哥和蒂姆下周都不会去参观艺术展，因为他们那时都要上课。</p><p><strong>词组</strong>：<code>neither…nor…</code> 既不……也不……（就近原则）；<code>decide to do sth.</code> 决定做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:30，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·就近原则）：either...or / neither...nor 连接的并列主语——就近一致</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 <strong>三群恒复数</strong>：people、police、cattle</p><p><strong>集体名词看意义</strong>：整体单、成员复</p><p><strong>the number 单，a number 复</strong></p><p><strong>就近看邻居，就远看主干</strong></p><p><strong>one of 从句复数，the only one of 从句单数</strong></p></div><p>延伸阅读：主谓一致 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,241),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/9/`},{default:i(()=>[...l[5]||=[e(`← 第 9 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/11/`},{default:i(()=>[...l[7]||=[e(`第 11 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};